values (
  'es-trivia-tenis-grand-slams',
  'Trivia de tenis: ¿cuánto sabes de los Grand Slams?',
  'Melbourne, París, Londres y Nueva York: trofeos, tradiciones y los cuatro escenarios que coronan el año del tenis.',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿En qué ciudad se juega el Abierto de Australia?","options":[{"id":"a","text":"Melbourne","is_correct":true},{"id":"b","text":"Sídney","is_correct":false},{"id":"c","text":"Adelaida","is_correct":false},{"id":"d","text":"Perth","is_correct":false}],"explanation":"El Abierto de Australia se juega en Melbourne Park desde 1988."},{"id":"q2","question":"¿Quién fue Roland Garros, el nombre del torneo parisino?","options":[{"id":"a","text":"El fundador del torneo","is_correct":false},{"id":"b","text":"Un campeón francés de los años 20","is_correct":false},{"id":"c","text":"El arquitecto del estadio","is_correct":false},{"id":"d","text":"Un aviador de la Primera Guerra Mundial","is_correct":true}],"explanation":"Roland Garros fue un aviador francés caído en 1918; el estadio tomó su nombre en 1928."},{"id":"q3","question":"¿Qué Grand Slam abre el calendario cada año?","options":[{"id":"a","text":"Wimbledon","is_correct":false},{"id":"b","text":"El Abierto de Australia","is_correct":true},{"id":"c","text":"Roland Garros","is_correct":false},{"id":"d","text":"El US Open","is_correct":false}],"explanation":"El orden es Abierto de Australia (enero), Roland Garros, Wimbledon y US Open."},{"id":"q4","question":"¿Qué trofeo recibe la campeona individual de Wimbledon?","options":[{"id":"a","text":"La Copa Daphne Akhurst","is_correct":false},{"id":"b","text":"El Venus Rosewater Dish","is_correct":true},{"id":"c","text":"La Copa Suzanne Lenglen","is_correct":false},{"id":"d","text":"La Copa de los Mosqueteros","is_correct":false}],"explanation":"El Venus Rosewater Dish se entrega desde 1886; las otras copas son de Australia y Roland Garros."},{"id":"q5","question":"¿Cómo se llama el estadio más grande del tenis, escenario de la final del US Open?","options":[{"id":"a","text":"Rod Laver Arena","is_correct":false},{"id":"b","text":"Centre Court","is_correct":false},{"id":"c","text":"Philippe-Chatrier","is_correct":false},{"id":"d","text":"Arthur Ashe Stadium","is_correct":true}],"explanation":"El Arthur Ashe Stadium tiene casi 24.000 localidades y se inauguró en 1997."},{"id":"q6","question":"¿Qué exige el famoso código de vestimenta de Wimbledon?","options":[{"id":"a","text":"Vestir casi totalmente de blanco","is_correct":true},{"id":"b","text":"Llevar el verde y morado del club","is_correct":false},{"id":"c","text":"Jugar sin logos de patrocinadores","is_correct":false},{"id":"d","text":"Usar pantalón o falda larga","is_correct":false}],"explanation":"La regla del blanco casi total en el All England Club viene de la época victoriana."},{"id":"q7","question":"¿Qué tradición gastronómica asocia el público con Wimbledon?","options":[{"id":"a","text":"Fish and chips","is_correct":false},{"id":"b","text":"Té con sándwiches de pepino","is_correct":false},{"id":"c","text":"Fresas con crema","is_correct":true},{"id":"d","text":"Pastel de carne","is_correct":false}],"explanation":"Las fresas con crema son el clásico de Wimbledon desde las primeras ediciones del torneo."},{"id":"q8","question":"¿Qué apodo recibe el Abierto de Australia entre los jugadores?","options":[{"id":"a","text":"El Slam del Pacífico","is_correct":false},{"id":"b","text":"El Slam dorado","is_correct":false},{"id":"c","text":"El Slam de medianoche","is_correct":false},{"id":"d","text":"El «Happy Slam»","is_correct":true}],"explanation":"Al Abierto de Australia lo llaman el Happy Slam por su ambiente relajado de enero."}]'::jsonb,
