values (
  'en-federer-nadal-trivia',
  'Tennis Trivia: Federer and Nadal, the Rivalry of an Era',
  'The Swiss maestro and the King of Clay: records, epic finals and the rivalry that defined two decades of tennis.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Which country is Roger Federer from?","options":[{"id":"a","text":"Austria","is_correct":false},{"id":"b","text":"Germany","is_correct":false},{"id":"c","text":"Sweden","is_correct":false},{"id":"d","text":"Switzerland","is_correct":true}],"explanation":"Federer was born in Basel, Switzerland, in 1981."},{"id":"q2","question":"On which Spanish island was Rafael Nadal born and raised?","options":[{"id":"a","text":"Tenerife","is_correct":false},{"id":"b","text":"Mallorca","is_correct":true},{"id":"c","text":"Ibiza","is_correct":false},{"id":"d","text":"Gran Canaria","is_correct":false}],"explanation":"Nadal was born in Manacor, Mallorca, and still keeps his academy there."},{"id":"q3","question":"How many Roland Garros titles did Nadal win in his career?","options":[{"id":"a","text":"12","is_correct":false},{"id":"b","text":"18","is_correct":false},{"id":"c","text":"14","is_correct":true},{"id":"d","text":"16","is_correct":false}],"explanation":"Fourteen titles in Paris between 2005 and 2022, the most dominant record at any major."},{"id":"q4","question":"How many Wimbledon titles did Federer win in his career?","options":[{"id":"a","text":"8","is_correct":true},{"id":"b","text":"7","is_correct":false},{"id":"c","text":"9","is_correct":false},{"id":"d","text":"10","is_correct":false}],"explanation":"Federer won eight Wimbledons between 2003 and 2017, a men''s record at the tournament."},{"id":"q5","question":"The 2008 Wimbledon final, often called the greatest match ever played, ended how?","options":[{"id":"a","text":"10-8 to Nadal in the fifth set","is_correct":false},{"id":"b","text":"8-6 to Federer in the fifth set","is_correct":false},{"id":"c","text":"7-5 to Federer in the fifth set","is_correct":false},{"id":"d","text":"9-7 to Nadal in the fifth set","is_correct":true}],"explanation":"Nadal beat the five-time defending champion 9-7 in the fifth, finishing in near darkness."},{"id":"q6","question":"Who coached Nadal for most of his career?","options":[{"id":"a","text":"His uncle Toni Nadal","is_correct":true},{"id":"b","text":"Carlos Moyá","is_correct":false},{"id":"c","text":"His father Sebastián","is_correct":false},{"id":"d","text":"His uncle Miguel Ángel","is_correct":false}],"explanation":"Toni Nadal coached Rafa from childhood until 2017; Miguel Ángel, his other uncle, played football for Barcelona."},{"id":"q7","question":"Federer holds the record for most consecutive weeks as world No. 1. How many?","options":[{"id":"a","text":"160","is_correct":false},{"id":"b","text":"237","is_correct":true},{"id":"c","text":"200","is_correct":false},{"id":"d","text":"310","is_correct":false}],"explanation":"He stayed on top for 237 straight weeks, from February 2004 to August 2008."},{"id":"q8","question":"Between 2005 and 2007, Nadal won a record streak of consecutive matches on clay. How many?","options":[{"id":"a","text":"65","is_correct":false},{"id":"b","text":"99","is_correct":false},{"id":"c","text":"55","is_correct":false},{"id":"d","text":"81","is_correct":true}],"explanation":"The 81-match clay streak ended when Federer beat him in the 2007 Hamburg final."}]'::jsonb,
  null,
  array['tennis', 'federer', 'nadal', 'sports', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
