  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿De qué ciudad suiza es Roger Federer?","options":[{"id":"a","text":"Ginebra","is_correct":false},{"id":"b","text":"Zúrich","is_correct":false},{"id":"c","text":"Basilea","is_correct":true},{"id":"d","text":"Berna","is_correct":false}],"explanation":"Federer nació en Basilea en 1981."},{"id":"q2","question":"¿En qué pueblo de Mallorca nació Rafa Nadal?","options":[{"id":"a","text":"Palma","is_correct":false},{"id":"b","text":"Alcúdia","is_correct":false},{"id":"c","text":"Andratx","is_correct":false},{"id":"d","text":"Manacor","is_correct":true}],"explanation":"Nadal nació en Manacor en 1986, donde hoy tiene su academia."},{"id":"q3","question":"¿Cuántos títulos de Roland Garros ganó Nadal en su carrera?","options":[{"id":"a","text":"12","is_correct":false},{"id":"b","text":"14","is_correct":true},{"id":"c","text":"16","is_correct":false},{"id":"d","text":"18","is_correct":false}],"explanation":"Catorce títulos en París entre 2005 y 2022, el récord más dominante en un major."},{"id":"q4","question":"¿Cuántos Wimbledon ganó Federer en su carrera?","options":[{"id":"a","text":"6","is_correct":false},{"id":"b","text":"7","is_correct":false},{"id":"c","text":"9","is_correct":false},{"id":"d","text":"8","is_correct":true}],"explanation":"Ocho Wimbledons entre 2003 y 2017, el récord masculino del torneo."},{"id":"q5","question":"¿En qué torneo jugó Federer su último partido antes de retirarse en 2022?","options":[{"id":"a","text":"Laver Cup","is_correct":true},{"id":"b","text":"Wimbledon","is_correct":false},{"id":"c","text":"US Open","is_correct":false},{"id":"d","text":"ATP Finals","is_correct":false}],"explanation":"Se despidió en la Laver Cup de Londres, jugando dobles junto a Nadal."},{"id":"q6","question":"¿Quién entrenó a Nadal durante la mayor parte de su carrera?","options":[{"id":"a","text":"Carlos Moyá","is_correct":false},{"id":"b","text":"Su padre Sebastián","is_correct":false},{"id":"c","text":"Su tío Toni","is_correct":true},{"id":"d","text":"Su tío Miguel Ángel","is_correct":false}],"explanation":"Toni Nadal lo entrenó desde niño hasta 2017; su otro tío, Miguel Ángel, fue futbolista del Barcelona."},{"id":"q7","question":"¿Con qué mano juega Nadal?","options":[{"id":"a","text":"Con la derecha","is_correct":false},{"id":"b","text":"Con las dos por igual","is_correct":false},{"id":"c","text":"Con la izquierda","is_correct":true},{"id":"d","text":"Cambia según el golpe","is_correct":false}],"explanation":"Nadal juega de zurdo aunque en la vida diaria es diestro."},{"id":"q8","question":"¿Cuántos partidos seguidos ganó Nadal en arcilla entre 2005 y 2007, su récord en una superficie?","options":[{"id":"a","text":"81","is_correct":true},{"id":"b","text":"60","is_correct":false},{"id":"c","text":"100","is_correct":false},{"id":"d","text":"72","is_correct":false}],"explanation":"La racha de 81 partidos en arcilla terminó cuando Federer lo venció en la final de Hamburgo 2007."}]'::jsonb,
