insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-djokovic-serena-trivia',
  'Tennis Trivia: Djokovic and Serena Williams',
  'From Belgrade to Compton: questions on Novak Djokovic and Serena Williams, two of the greatest to hold a racket.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"Which country does Novak Djokovic represent?","options":[{"id":"a","text":"Croatia","is_correct":false},{"id":"b","text":"Serbia","is_correct":true},{"id":"c","text":"Montenegro","is_correct":false},{"id":"d","text":"Slovenia","is_correct":false}],"explanation":"Djokovic was born in Belgrade in 1987 and led Serbia to its first Davis Cup in 2010."},{"id":"q2","question":"Where did Djokovic win his first Grand Slam singles title?","options":[{"id":"a","text":"Wimbledon 2007","is_correct":false},{"id":"b","text":"US Open 2008","is_correct":false},{"id":"c","text":"Australian Open 2008","is_correct":true},{"id":"d","text":"Roland Garros 2009","is_correct":false}],"explanation":"He won the 2008 Australian Open at 20, beating Jo-Wilfried Tsonga in the final."},{"id":"q3","question":"What did Djokovic complete by winning the Olympic gold medal at Paris 2024?","options":[{"id":"a","text":"A calendar-year Grand Slam","is_correct":false},{"id":"b","text":"The career Golden Slam","is_correct":true},{"id":"c","text":"A tenth Wimbledon title","is_correct":false},{"id":"d","text":"His first Davis Cup","is_correct":false}],"explanation":"The Paris gold was the only big title he was missing: he had already won all four majors."},{"id":"q4","question":"The ''Nole Slam'' refers to Djokovic doing what across 2015 and 2016?","options":[{"id":"a","text":"Holding all four major titles at once","is_correct":true},{"id":"b","text":"Winning all four majors in one year","is_correct":false},{"id":"c","text":"Going a full season unbeaten","is_correct":false},{"id":"d","text":"Winning four straight Australian Opens","is_correct":false}],"explanation":"From Wimbledon 2015 to Roland Garros 2016 he held all four titles, on three different surfaces."},{"id":"q5","question":"The longest Grand Slam final ever, 5 hours 53 minutes at the 2012 Australian Open, was Djokovic against whom?","options":[{"id":"a","text":"Roger Federer","is_correct":false},{"id":"b","text":"Andy Murray","is_correct":false},{"id":"c","text":"Stan Wawrinka","is_correct":false},{"id":"d","text":"Rafael Nadal","is_correct":true}],"explanation":"Djokovic beat Nadal 7-5 in the fifth; both needed chairs for the trophy ceremony."},{"id":"q6","question":"Where did Serena Williams win her first Grand Slam singles title, aged 17?","options":[{"id":"a","text":"Wimbledon 2000","is_correct":false},{"id":"b","text":"Roland Garros 1999","is_correct":false},{"id":"c","text":"US Open 1999","is_correct":true},{"id":"d","text":"Australian Open 1998","is_correct":false}],"explanation":"She beat Martina Hingis in the 1999 US Open final, the first of her 23 majors."},{"id":"q7","question":"Serena''s older sister, also a multiple Grand Slam champion, is?","options":[{"id":"a","text":"Lyndrea","is_correct":false},{"id":"b","text":"Cori","is_correct":false},{"id":"c","text":"Sloane","is_correct":false},{"id":"d","text":"Venus","is_correct":true}],"explanation":"Venus Williams won seven majors; the sisters played nine Grand Slam finals against each other."},{"id":"q8","question":"Serena won her 23rd and last Grand Slam title while early in her pregnancy, at which event?","options":[{"id":"a","text":"Australian Open 2017","is_correct":true},{"id":"b","text":"Wimbledon 2016","is_correct":false},{"id":"c","text":"US Open 2015","is_correct":false},{"id":"d","text":"Roland Garros 2015","is_correct":false}],"explanation":"She beat Venus in the 2017 Australian Open final and gave birth later that year."}]'::jsonb,
  null,
  array['tennis', 'djokovic', 'serena williams', 'sports', 'trivia']::text[],
  3,
  'published',
