values (
  'en-tennis-surfaces-rules-trivia',
  'Tennis Trivia: Surfaces and Rules of the Game',
  'Clay, grass, hard courts and the strange arithmetic of 15-30-40: test how well you know tennis surfaces and rules.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"On what surface are the US Open and the Australian Open played?","options":[{"id":"a","text":"Grass","is_correct":false},{"id":"b","text":"Clay","is_correct":false},{"id":"c","text":"Hard courts","is_correct":true},{"id":"d","text":"Carpet","is_correct":false}],"explanation":"Both are hard-court majors: the US Open uses DecoTurf and the Australian Open Plexicushion."},{"id":"q2","question":"In 2008 the Australian Open changed its courts to which colour?","options":[{"id":"a","text":"Green","is_correct":false},{"id":"b","text":"Blue","is_correct":true},{"id":"c","text":"Red","is_correct":false},{"id":"d","text":"Purple","is_correct":false}],"explanation":"The tournament switched from the old green Rebound Ace to blue Plexicushion in 2008."},{"id":"q3","question":"Green clay (Har-Tru), used at some U.S. events, is made from what?","options":[{"id":"a","text":"Crushed brick","is_correct":false},{"id":"b","text":"Dyed sand","is_correct":false},{"id":"c","text":"Shredded rubber","is_correct":false},{"id":"d","text":"Crushed stone","is_correct":true}],"explanation":"Har-Tru is crushed basalt rock; European red clay, by contrast, is crushed brick."},{"id":"q4","question":"What is a ''deuce'' in a tennis game?","options":[{"id":"a","text":"The score tied at 40-40","is_correct":true},{"id":"b","text":"A serve that hits the net","is_correct":false},{"id":"c","text":"The tiebreak game","is_correct":false},{"id":"d","text":"A double fault","is_correct":false}],"explanation":"Deuce means 40-40; from there a player needs two points in a row to take the game."},{"id":"q5","question":"To win a game from deuce, a player must win how many consecutive points?","options":[{"id":"a","text":"One","is_correct":false},{"id":"b","text":"Three","is_correct":false},{"id":"c","text":"Two","is_correct":true},{"id":"d","text":"Four","is_correct":false}],"explanation":"After deuce come advantage and game point: two consecutive points close the game."},{"id":"q6","question":"At what score in a set is a tiebreak normally played?","options":[{"id":"a","text":"5-5","is_correct":false},{"id":"b","text":"6-5","is_correct":false},{"id":"c","text":"7-6","is_correct":false},{"id":"d","text":"6-6","is_correct":true}],"explanation":"A set tied at six games each is decided by a tiebreak, usually to seven points."},{"id":"q7","question":"Men''s singles matches at the Grand Slams are played at most over how many sets?","options":[{"id":"a","text":"Five","is_correct":true},{"id":"b","text":"Three","is_correct":false},{"id":"c","text":"Four","is_correct":false},{"id":"d","text":"Seven","is_correct":false}],"explanation":"Men''s majors are best of five sets; women''s and most tour matches are best of three."},{"id":"q8","question":"Since 2022, how do all four majors decide a final set tied at 6-6?","options":[{"id":"a","text":"Play continues until a two-game lead","is_correct":false},{"id":"b","text":"A 10-point tiebreak","is_correct":true},{"id":"c","text":"A standard 7-point tiebreak","is_correct":false},{"id":"d","text":"A single deciding point","is_correct":false}],"explanation":"Since 2022 the four majors use a 10-point match tiebreak at 6-6 in the last set."}]'::jsonb,
