insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-tennis-history-trivia',
  'Tennis Trivia: Historic Matches and Moments',
  'Epic marathons, barrier-breaking champions and the matches that changed tennis forever: how much do you remember?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"The longest match in tennis history (11 hours 5 minutes, fifth set 70-68) at Wimbledon 2010 was played between?","options":[{"id":"a","text":"Federer and Nadal","is_correct":false},{"id":"b","text":"Isner and Mahut","is_correct":true},{"id":"c","text":"Djokovic and Nadal","is_correct":false},{"id":"d","text":"McEnroe and Borg","is_correct":false}],"explanation":"John Isner beat Nicolas Mahut over three days; Wimbledon put a plaque on Court 18."},{"id":"q2","question":"The Open Era began in which year, when the majors admitted professional players?","options":[{"id":"a","text":"1960","is_correct":false},{"id":"b","text":"1973","is_correct":false},{"id":"c","text":"1968","is_correct":true},{"id":"d","text":"1980","is_correct":false}],"explanation":"Roland Garros 1968 was the first major open to amateurs and professionals alike."},{"id":"q3","question":"Who was the first Black man to win Wimbledon, in 1975?","options":[{"id":"a","text":"Yannick Noah","is_correct":false},{"id":"b","text":"Stan Smith","is_correct":false},{"id":"c","text":"Jimmy Connors","is_correct":false},{"id":"d","text":"Arthur Ashe","is_correct":true}],"explanation":"Arthur Ashe beat defending champion Jimmy Connors in the 1975 final."},{"id":"q4","question":"The first Black player to win a Grand Slam singles title was?","options":[{"id":"a","text":"Arthur Ashe","is_correct":false},{"id":"b","text":"Althea Gibson","is_correct":true},{"id":"c","text":"Venus Williams","is_correct":false},{"id":"d","text":"Zina Garrison","is_correct":false}],"explanation":"Althea Gibson won Roland Garros in 1956, then Wimbledon and the US Open in 1957 and 1958."},{"id":"q5","question":"The youngest men''s Wimbledon champion, at 17 in 1985, was?","options":[{"id":"a","text":"Björn Borg","is_correct":false},{"id":"b","text":"Michael Chang","is_correct":false},{"id":"c","text":"Boris Becker","is_correct":true},{"id":"d","text":"Mats Wilander","is_correct":false}],"explanation":"Becker won unseeded at 17 years and 7 months; Chang was 17 too at his 1989 Roland Garros title."},{"id":"q6","question":"Federer announced himself at Wimbledon 2001 by ending whose reign?","options":[{"id":"a","text":"Andre Agassi","is_correct":false},{"id":"b","text":"Goran Ivanišević","is_correct":false},{"id":"c","text":"Pat Rafter","is_correct":false},{"id":"d","text":"Pete Sampras","is_correct":true}],"explanation":"The 19-year-old Federer beat Sampras in the fourth round, ending his 31-match Wimbledon win streak."},{"id":"q7","question":"Which 1969 Wimbledon match of 112 games pushed the sport to adopt the tiebreak?","options":[{"id":"a","text":"Laver vs Rosewall","is_correct":false},{"id":"b","text":"González vs Pasarell","is_correct":true},{"id":"c","text":"Borg vs Gerulaitis","is_correct":false},{"id":"d","text":"Ashe vs Okker","is_correct":false}],"explanation":"Pancho González, 41, beat Charlie Pasarell over two days; the marathon hastened the tiebreak."},{"id":"q8","question":"The youngest Grand Slam singles champion of the Open Era, at 16 in 1997, was?","options":[{"id":"a","text":"Monica Seles","is_correct":false},{"id":"b","text":"Steffi Graf","is_correct":false},{"id":"c","text":"Tracy Austin","is_correct":false},{"id":"d","text":"Martina Hingis","is_correct":true}],"explanation":"Hingis won the 1997 Australian Open at 16 years and 3 months."}]'::jsonb,
  null,
  array['tennis', 'history', 'sports', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
