  (select id from public.categories where slug = 'sports'),
  '[{"id":"q1","question":"¿Cuánto duró el partido más largo de la historia, Isner vs Mahut en Wimbledon 2010?","options":[{"id":"a","text":"8 horas justas","is_correct":false},{"id":"b","text":"6 horas y media","is_correct":false},{"id":"c","text":"14 horas","is_correct":false},{"id":"d","text":"11 horas y 5 minutos","is_correct":true}],"explanation":"Se jugó en tres días y el quinto set acabó 70-68; Wimbledon puso una placa en la pista 18."},{"id":"q2","question":"¿En qué año comenzó la Era Open, cuando los majors admitieron a jugadores profesionales?","options":[{"id":"a","text":"1958","is_correct":false},{"id":"b","text":"1973","is_correct":false},{"id":"c","text":"1968","is_correct":true},{"id":"d","text":"1984","is_correct":false}],"explanation":"Roland Garros 1968 fue el primer major abierto a amateurs y profesionales."},{"id":"q3","question":"¿Quién fue el primer hombre negro en ganar Wimbledon, en 1975?","options":[{"id":"a","text":"Arthur Ashe","is_correct":true},{"id":"b","text":"Yannick Noah","is_correct":false},{"id":"c","text":"Stan Smith","is_correct":false},{"id":"d","text":"Jimmy Connors","is_correct":false}],"explanation":"Arthur Ashe venció al campeón defensor Jimmy Connors en la final de 1975."},{"id":"q4","question":"¿Quién fue la primera tenista negra en ganar un título de Grand Slam?","options":[{"id":"a","text":"Venus Williams","is_correct":false},{"id":"b","text":"Zina Garrison","is_correct":false},{"id":"c","text":"Althea Gibson","is_correct":true},{"id":"d","text":"Serena Williams","is_correct":false}],"explanation":"Althea Gibson ganó Roland Garros en 1956 y luego Wimbledon y el US Open en 1957 y 1958."},{"id":"q5","question":"¿Con qué edad ganó Boris Becker Wimbledon en 1985, como campeón masculino más joven?","options":[{"id":"a","text":"18 años","is_correct":false},{"id":"b","text":"17 años","is_correct":true},{"id":"c","text":"19 años","is_correct":false},{"id":"d","text":"20 años","is_correct":false}],"explanation":"Becker ganó sin ser cabeza de serie con 17 años y 7 meses."},{"id":"q6","question":"¿Qué grito hizo famoso John McEnroe durante Wimbledon 1981?","options":[{"id":"a","text":"«New balls, please!»","is_correct":false},{"id":"b","text":"«Game, set, match!»","is_correct":false},{"id":"c","text":"«Are you kidding me?»","is_correct":false},{"id":"d","text":"«You cannot be serious!»","is_correct":true}],"explanation":"«You cannot be serious!» quedó como el berrinche más célebre del tenis; McEnroe ganó ese Wimbledon."},{"id":"q7","question":"¿Qué partido de Wimbledon 1969, con 112 juegos, impulsó la adopción del tiebreak?","options":[{"id":"a","text":"González vs Pasarell","is_correct":true},{"id":"b","text":"Laver vs Rosewall","is_correct":false},{"id":"c","text":"Borg vs Gerulaitis","is_correct":false},{"id":"d","text":"Ashe vs Okker","is_correct":false}],"explanation":"Pancho González, de 41 años, venció a Charlie Pasarell en dos días; la maratón aceleró el tiebreak."},{"id":"q8","question":"¿Quién es la campeona individual de Grand Slam más joven de la Era Open?","options":[{"id":"a","text":"Monica Seles","is_correct":false},{"id":"b","text":"Steffi Graf","is_correct":false},{"id":"c","text":"Martina Hingis","is_correct":true},{"id":"d","text":"Tracy Austin","is_correct":false}],"explanation":"Hingis ganó el Abierto de Australia 1997 con 16 años y 3 meses."}]'::jsonb,
